35	    /// Enforce naming conventions for everything across a codebase.
36	    ///
37	    /// Enforcing [naming conventions](https://en.wikipedia.org/wiki/Naming_convention_(programming)) helps to keep the codebase consistent,
38	    /// and reduces overhead when thinking about the name [case] of a variable.
39	    ///
40	    /// ## Naming conventions
41	    ///
42	    /// All names can be prefixed and suffixed by underscores `_` and dollar signs `$`.
43	    ///
44	    /// ### Variable names
45	    ///
46	    /// All variables, including function parameters and catch parameters, are in [`camelCase`].
47	    ///
48	    /// Additionally, top-level variables declared as `const` or `var` may be in [`CONSTANT_CASE`] or [`PascalCase`].
49	    /// Top-level variables are declared at module or script level.
50	    /// Variables declared in a TypeScript `module` or `namespace` are also considered top-level.
51	    ///
52	    /// ```js
53	    /// function f(param, _unusedParam) {
54	    ///     let localValue = 0;
55	    ///     try {
56	    ///         /* ... */
57	    ///     } catch (customError) {
58	    ///         /* ... */
59	    ///     }
60	    /// }
61	    ///
62	    /// export const A_CONSTANT = 5;
63	    ///
64	    /// export const Person = class {}
65	    ///
66	    /// let aVariable = 0;
67	    ///
68	    /// export namespace ns {
69	    ///     export const ANOTHER_CONSTANT = "";
70	    /// }
71	    /// ```
72	    ///
73	    /// Examples of incorrect names:
74	    ///
75	    /// ```js,expect_diagnostic
76	    /// let a_value = 0;
77	    /// ```
78	    ///
79	    /// ```js,expect_diagnostic
80	    /// const fooYPosition = 0;
81	    /// ```
82	    ///
83	    /// ```js,expect_diagnostic
84	    /// function f(FirstParam) {}
85	    /// ```
86	    ///
87	    /// ### Function names
88	    ///
89	    /// A `function` name is in [`camelCase`] or [`PascalCase`].
90	    ///
91	    /// ```jsx
92	    /// function trimString(s) { /*...*/ }
93	    ///
94	    /// function Component() {
95	    ///     return <div></div>;
96	    /// }
97	    /// ```
98	    ///
99	    /// ### TypeScript `enum` names
100	    ///
101	    /// A _TypeScript_ `enum` name is in [`PascalCase`].
102	    ///
103	    /// `enum` members are by default in [`PascalCase`].
104	    /// However, you can configure the [case] of `enum` members.
105	    /// See [options](#options) for more details.
106	    ///
107	    /// ```ts
108	    /// enum Status {
109	    ///     Open,
110	    ///     Close,
111	    /// }
112	    /// ```
113	    ///
114	    /// ### Classes
115	    ///
116	    /// - A class name is in [`PascalCase`].
117	    ///
118	    /// - Static property and static getter names are in [`camelCase`] or [`CONSTANT_CASE`].
119	    ///
120	    /// - Class property and method names are in [`camelCase`].
121	    ///
122	    /// ```js
123	    /// class Person {
124	    ///     static MAX_FRIEND_COUNT = 256;
125	    ///
126	    ///     static get SPECIAL_PERSON_INSTANCE() { /*...*/ }
127	    ///
128	    ///     initializedProperty = 0;
129	    ///
130	    ///     specialMethod() {}
131	    /// }
132	    /// ```
133	    ///
134	    /// ### TypeScript `type` aliases and `interface`
135	    ///
136	    /// - A `type` alias or an interface name are in [`PascalCase`].
137	    ///
138	    /// - Property and method names in a type are in [`camelCase`].
139	    ///
140	    /// - `readonly` property and getter names can also be in [`CONSTANT_CASE`].
141	    ///
142	    /// ```ts
143	    /// type Named = {
144	    ///     readonly fullName: string;
145	    ///
146	    ///     specialMethod(): void;
147	    /// };
148	    ///
149	    /// interface Named {
150	    ///     readonly fullName: string;
151	    ///
152	    ///     specialMethod(): void;
153	    /// }
154	    ///
155	    /// interface PersonConstructor {
156	    ///     readonly MAX_FRIEND_COUNT: number;
157	    ///
158	    ///     get SPECIAL_PERSON_INSTANCE(): Person;
159	    ///
160	    ///     new(): Person;
161	    /// }
162	    /// ```
163	    ///
164	    /// Examples of an incorrect type alias:
165	    ///
166	    /// ```ts,expect_diagnostic
167	    /// type person = { fullName: string };
168	    /// ```
169	    ///
170	    /// ### Literal object property and method names
171	    ///
172	    /// Literal object property and method names are in [`camelCase`].
173	    ///
174	    /// ```js
175	    /// const alice = {
176	    ///     fullName: "Alice",
177	    /// }
178	    /// ```
179	    ///
180	    /// Example of an incorrect name:
181	    ///
182	    /// ```js,expect_diagnostic
183	    /// const alice = {
184	    ///     FULL_NAME: "Alice",
185	    /// }
186	    /// ```
187	    ///
188	    /// ### Imported and exported module aliases
189	    ///
190	    /// Imported and exported module aliases are in [`camelCase`] or [`PascalCase`].
191	    ///
