17	declare_rule! {
18	    /// Enforce naming conventions for JavaScript and TypeScript filenames.
19	    ///
20	    /// Enforcing [naming conventions](https://en.wikipedia.org/wiki/Naming_convention_(programming)) helps to keep the codebase consistent.
21	    ///
22	    /// A filename consists of two parts: a name and a set of consecutive extension.
23	    /// For instance, `my-filename.test.js` has `my-filename` as name, and two consecutive extensions: `.test` and `.js`.
24	    ///
25	    /// The name of a filename can start with a dot, be prefixed and suffixed by underscores `_`.
26	    /// For example, `.filename.js`, `__filename__.js`, or even `.__filename__.js`.
27	    ///
28	    /// By default, the rule ensures that the filename is either in [`camelCase`], [`kebab-case`], [`snake_case`],
29	    /// or equal to the name of one export in the file.
30	    ///
31	    /// ## Options
32	    ///
33	    /// The rule provides two options that are detailed in the following subsections.
34	    ///
35	    /// ```json
36	    /// {
37	    ///     "//": "...",
38	    ///     "options": {
39	    ///         "strictCase": false,
40	    ///         "enumMemberCase": ["camelCase", "export"]
41	    ///     }
42	    /// }
43	    /// ```
44	    ///
45	    /// ### strictCase
46	    ///
47	    /// When this option is set to `true`, it forbids consecutive uppercase characters in [`camelCase`].
48	    /// For instance,  when the option is set to `true`, `agentID` will throw an error.
49	    /// This name should be renamed to `agentId`.
50	    ///
51	    /// When the option is set to `false`, consecutive uppercase characters are allowed.
52	    /// `agentID` is so valid.
53	    ///
54	    /// Default: `true`
55	    ///
56	    /// ### filenameCases
57	    ///
58	    /// By default, the rule enforces that the filename  is either in [`camelCase`], [`kebab-case`], [`snake_case`], or equal to the name of one export in the file.
59	    ///
60	    /// You can enforce a stricter convention by setting `filenameCases` option.
61	    /// `filenameCases` accepts an array of cases among the following cases: [`camelCase`], [`kebab-case`], [`PascalCase`], [`snake_case`], and `export`.
62	    ///
63	    /// [case]: https://en.wikipedia.org/wiki/Naming_convention_(programming)#Examples_of_multiple-word_identifier_formats
64	    /// [`camelCase`]: https://en.wikipedia.org/wiki/Camel_case
65	    /// [`kebab-case`]: https://en.wikipedia.org/wiki/Letter_case#Kebab_case
66	    /// [`PascalCase`]: https://en.wikipedia.org/wiki/Camel_case
67	    /// [`snake_case`]: https://en.wikipedia.org/wiki/Snake_case
68	    pub(crate) UseFilenamingConvention {
69	        version: "1.5.0",
70	        name: "useFilenamingConvention",
71	        source: RuleSource::EslintUnicorn("filename-case"),
72	        source_kind: RuleSourceKind::Inspired,
73	        recommended: false,
74	    }
75	}
