77	impl Rule for UseFilenamingConvention {
78	    type Query = SemanticServices;
79	    type State = FileNamingConventionState;
80	    type Signals = Option<Self::State>;
81	    type Options = FilenamingConventionOptions;
82	
83	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
84	        let file_name = ctx.file_path().file_name()?.to_str()?;
85	        let FilenamingConventionOptions {
86	            strict_case,
87	            filename_cases,
88	        } = ctx.options();
89	        let allowed_cases = filename_cases.cases();
90	        let mut splitted = file_name.split('.');
91	        let name = splitted.next()?;
92	        let name = if name.is_empty() {
93	            // The filename starts with a dot
94	            splitted.next()?
95	        } else {
96	            name
97	        };
98	        // Check extension case
99	        for extension in splitted {
100	            let case = Case::identify(extension, true);
101	            if case != Case::Lower {
102	                return Some(FileNamingConventionState::Extension);
103	            }
104	        }
105	        // Check filename case
106	        if !allowed_cases.is_empty() {
107	            let trimmed_name = name.trim_matches('_');
108	            let case = Case::identify(trimmed_name, *strict_case);
109	            for allowed_case in allowed_cases {
110	                if case.is_compatible_with(allowed_case) {
111	                    return None;
112	                }
113	            }
114	        }
115	        if filename_cases.0.contains(&FilenameCase::Export) {
116	            // If no exported binding has the file name, then reports the filename
117	            let model = ctx.model();
118	            model
119	                .all_bindings()
120	                .map(|binding| binding.tree())
121	                .filter(|binding| model.is_exported(binding))
122	                .filter_map(|exported_binding| exported_binding.name_token().ok())
123	                .all(|exported_name_token| exported_name_token.text_trimmed() != name)
124	                .then_some(FileNamingConventionState::Filename)
125	        } else {
126	            Some(FileNamingConventionState::Filename)
127	        }
128	    }
